INSERT INTO `v1_950d97f211b0a8ab6d7ab0f4eab3584cf3a45a99fe79cd926d066071543e4299` VALUES ("", 104511, 3, "", "", 0.2, 513049, "nop_13_kuka_talk_memory1", "", 1, 513);
